from math import log10, log2

"""# Entropy"""

# ----------------------------------------------------
# Step 1 : Entropy of Dataset (before split)
#-----------------------------------------------------

#entropy before the split
#entropy of dataset (Repaid=6, Defaulted=4)
entropy_employment_status=-6/10*log2(6/10)-4/10*log2(4/10)
print('the entropy_employment_status =',entropy_employment_status)

"""**Entropy - Employment_Status**

Split Table : Below

![image.png](data:image/png;base64,)
"""

#----------------------------------------------------
# Step 2 : Entropy of Employment_Status
# -----------------------------------------------------

#after splitting into dataset
#Employment -> Employed,unemployed
# -> Employed [6 all Repaid]
entropy_employed=-6/6*log2(6/6)
print('the entropy_employed =',entropy_employed)
# -> Unemployed [4 all Defaulted]
entropy_unemployed=-4/4*log2(4/4)
print('the entropy_unemployed =',entropy_unemployed)
print(' ')

information_gain_employment_status=10/10*entropy_employment_status-6/10*entropy_employed-4/10*entropy_unemployed
print('the information_gain_employment_status =',round(information_gain_employment_status,3))

"""**Entropy - Housing Status**"""

#entropy before the split
entropy_housing_status=entropy_employment_status
print('the entropy_housing_status =',entropy_housing_status)

"""Owner-5; Rented-5; Total - 10

Split Table : Below

![image.png](data:image/png;base64,)
"""

#----------------------------------------------------
# Step 3 : Hosuing_Status
# -----------------------------------------------------

#after splitting into dataset
## Hosuing -> Rented,Owner
# Rented = 5 -> 3 Repaid, 2 Defaulted
entropy_rented=-3/5*log2(3/5)-2/5*log2(2/5)
print('the entropy_rented =',entropy_rented)
# Owner = 5 -> 3 Repaid, 2 Defaulted
entropy_owner=-3/5*log2(3/5)-2/5*log2(2/5)
print('the entropy_owner =',entropy_owner)
print(' ')

information_gain_housing_status=10/10*entropy_housing_status-5/10*entropy_rented-5/10*entropy_owner
print('the information_gain_housing_status =',round(information_gain_housing_status,3))

"""**Entropy - Bank_Account**"""

#entropy before the split
entropy_bank_account=entropy_employment_status
print('the entropy_bank_account =',entropy_bank_account)

"""Active-5; None-5; Total - 10

Split Table : Below

![image.png](data:image/png;base64,)
"""

#----------------------------------------------------
# Step 4 : Bank_Account
# -----------------------------------------------------

#after splitting into dataset
# Bank_Account -> Active,None
# Active [ 5 all Repaid]
entropy_active=-5/5*log2(5/5)-0
print('the entropy_active =',entropy_active)
# None = 5 -> 1 Repaid, 4 Defaulted
entropy_none=-1/5*log2(1/5)-4/5*log2(4/5)
print('the entropy_none =',entropy_none)
print(' ')

information_gain_bank_account=10/10*entropy_bank_account-5/10*entropy_active-5/10*entropy_none
print('the information_gain_bank_account =',round(information_gain_bank_account,3))

"""**Best Information Gain**"""

# Final Comparision
print('\n Final Comparison:')
print ('information_gain_employment_status = ',round(information_gain_employment_status,3))
print ('information_gain_housing_status = ',round(information_gain_housing_status,3))
print ('information_gain_bank_account = ',round(information_gain_bank_account,3))

print('The best feature to split on is Employment_Status because it has the highest Information Gain.')

